using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class PRApply {
 const string P="Assets/Afrer_Seconds/05.Model/Props/1F/";
 static string R=>Path.GetFullPath(Application.dataPath+"/../../..");static string H=>R+"/SourceAssets/F1_PropRefinement/";static string O=>R+"/Docs/Review/2026-11-13_1F_PropRefinement/";
 static string Kind(Transform t){if(!t.name.StartsWith("F1_")||!t.parent||!t.parent.name.StartsWith("1F_"))return null;foreach(var k in new[]{"CableReel","ToolCart","Forklift","Press"})if(t.name.Contains("_"+k+"_"))return k;return t.name.EndsWith("_Chair")?"OfficeChair":null;}
 static Color C(string hex){ColorUtility.TryParseHtmlString(hex,out var c);return c;}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F edit required");if(File.Exists(O+"applied.json"))throw new Exception("Already applied; use scoped updates");
 var targets=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>Kind(t)!=null).ToArray();if(targets.Length!=11)throw new Exception("Expected 11 targets");
 foreach(string f in new[]{"PRPropLit.shader","PRPropForward.hlsl","PRPropGBuffer.hlsl","PRPropSurface.hlsl"}){if(File.Exists(P+f))throw new Exception("Unexpected preexisting asset "+f);File.Copy(H+f,P+f);AssetDatabase.ImportAsset(P+f,ImportAssetOptions.ForceSynchronousImport);}
 var shader=AssetDatabase.LoadAssetAtPath<Shader>(P+"PRPropLit.shader");if(!shader||ShaderUtil.ShaderHasError(shader))throw new Exception("Shader error");var mats=new Dictionary<string,Material>();
 void Mat(string n,string color,float metallic,float smooth,float mode,float wear=.35f){var m=new Material(shader){name="PR_M_"+n};m.SetColor("_BaseColor",C(color));m.SetFloat("_Metallic",metallic);m.SetFloat("_Smoothness",smooth);m.SetFloat("_AE_Mode",mode);m.SetFloat("_AE_WearAmount",wear);m.SetFloat("_AE_Seed",mats.Count*3.17f);m.enableInstancing=true;AssetDatabase.CreateAsset(m,P+m.name+".mat");mats[m.name]=m;}
 Mat("Green","#667363",.28f,.29f,20);Mat("Coat","#9A9B8C",.12f,.24f,20);Mat("Hazard","#B39A53",.17f,.27f,20);Mat("Steel","#6F7775",.72f,.38f,21);Mat("WornSteel","#8A8F8A",.82f,.46f,21);Mat("Dark","#282F2E",.23f,.24f,20);Mat("Rubber","#30312F",0,.14f,23);Mat("TireDust","#535047",0,.17f,23);Mat("Wood","#8B8068",0,.12f,22);Mat("WoodPale","#A0957C",0,.12f,22);Mat("WoodCrack","#39362D",0,.10f,25);Mat("Fabric","#676452",0,.055f,24);Mat("FabricWorn","#8A8370",0,.05f,24);Mat("Paper","#C6C1AA",0,.15f,25);Mat("Red","#984C3D",.1f,.26f,20);Mat("Indicator","#537468",.08f,.3f,20);Mat("Lamp","#B8B7A1",.08f,.42f,25);
 var report=JArray.Parse(File.ReadAllText(H+"models.json"));var prefabs=new Dictionary<string,GameObject>();string temp=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData)+"/Temp/AfterSeconds_PropRefinement_20261113/candidate/";
 foreach(var item in report){string n=(string)item["name"],path=P+n+".fbx";if(File.Exists(path))throw new Exception("Existing model "+path);File.Copy(temp+n+".fbx",path);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;mi.isReadable=false;mi.meshCompression=ModelImporterMeshCompression.Off;
 foreach(string name in item["materials"].Values<string>())mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),name),mats[name]);mi.SaveAndReimport();prefabs[n]=AssetDatabase.LoadAssetAtPath<GameObject>(path);}
 var result=new List<object>();foreach(var t in targets){string kind=Kind(t);var old=t.GetComponentsInChildren<Renderer>(true);var go=(GameObject)PrefabUtility.InstantiatePrefab(prefabs["PR_"+kind],t);go.name="PR_"+kind;go.transform.SetLocalPositionAndRotation(Vector3.zero,Quaternion.identity);go.transform.localScale=Vector3.one;
 foreach(var nested in go.GetComponentsInChildren<LODGroup>())UnityEngine.Object.DestroyImmediate(nested);
 foreach(var r in old)r.enabled=false;var lod=t.GetComponent<LODGroup>();if(!lod)lod=t.gameObject.AddComponent<LODGroup>();var nr=go.GetComponentsInChildren<Renderer>();var levels=new LOD[3];for(int i=0;i<3;i++)levels[i]=new LOD(new[]{.55f,.18f,.035f}[i],nr.Where(r=>r.name.EndsWith("LOD"+i)).ToArray());if(levels.Any(l=>l.renderers.Length!=1))throw new Exception("LOD renderer mismatch "+t.name);lod.SetLODs(levels);lod.RecalculateBounds();lod.fadeMode=LODFadeMode.None;
 result.Add(new{target=t.name,kind,oldRenderersDisabled=old.Select(r=>AnimationUtility.CalculateTransformPath(r.transform,null)).ToArray(),newRenderers=nr.Select(r=>r.name).ToArray()});}
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllText(O+"applied.json",JsonConvert.SerializeObject(result,Formatting.Indented));Selection.activeGameObject=targets.First(t=>Kind(t)=="CableReel").gameObject;return new{instances=result.Count,models=report.Count,materials=mats.Count};
 }
}
